using System.ComponentModel.DataAnnotations;

namespace sv_7a9fe366e5674f2183ffb8aae2511586.Models;

public class AppointmentFormModel
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    [Required(ErrorMessage = "Preferred doctor is required.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Appointment date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Time slot is required.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string? ReasonForVisit { get; set; }
}

public class ValidationResult
{
    public bool IsValid { get; set; }
    public Dictionary<string, string> FieldErrors { get; set; } = new();
}

using sv_7a9fe366e5674f2183ffb8aae2511586.Models;

namespace sv_7a9fe366e5674f2183ffb8aae2511586.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
        ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "11:30 AM", "2:30 PM", "4:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:30 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
            return Task.FromResult(new List<string>(slots));

        return Task.FromResult(new List<string>());
    }

    public Task<Models.ValidationResult> ValidatePatientAsync(AppointmentFormModel model)
    {
        var result = new Models.ValidationResult { IsValid = true };

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.IsValid = false;
            result.FieldErrors["Email"] = "Account has outstanding balance.";
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (model.InsuranceProvider == "None"
            && string.Equals(model.Doctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.IsValid = false;
            result.FieldErrors["Doctor"] = "Selected doctor does not accept self-pay patients.";
        }

        // Reject "10:00 AM" as taken (race-condition simulation)
        if (model.TimeSlot == "10:00 AM")
        {
            result.IsValid = false;
            result.FieldErrors["TimeSlot"] = "This slot is no longer available.";
        }

        return Task.FromResult(result);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_7a9fe366e5674f2183ffb8aae2511586.Models
@using sv_7a9fe366e5674f2183ffb8aae2511586.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey("Email"))
            {
                <div class="validation-message">@serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey("Doctor"))
                {
                    <div class="validation-message">@serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
                @if (dateError is not null)
                {
                    <div class="validation-message">@dateError</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">Back</button>
                <button type="button" class="btn btn-outline-primary" @onclick="CheckAvailability">
                    Check Availability
                </button>
                <button type="submit" class="btn btn-primary" disabled="@(!availabilityChecked)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentFormModel Model { get; set; } = new();

    private bool showStep2;
    private bool availabilityChecked;
    private bool bookingConfirmed;

    private List<string> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();
    private string? dateError;

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var step1Fields = new[]
        {
            editContext.Field(nameof(Model.PatientName)),
            editContext.Field(nameof(Model.Email)),
            editContext.Field(nameof(Model.Phone)),
            editContext.Field(nameof(Model.InsuranceProvider)),
        };

        var validator = new DataAnnotationsValidator();
        var messageStore = new ValidationMessageStore(editContext);

        // Trigger full validation then check only step-1 fields
        editContext.Validate();
        bool step1Valid = step1Fields.All(f => !editContext.GetValidationMessages(f).Any());

        if (step1Valid)
        {
            showStep2 = true;
            availabilityChecked = false;
            serverErrors.Clear();
        }
    }

    private async Task OnDoctorChanged()
    {
        availabilityChecked = false;
        serverErrors.Remove("Doctor");
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        availabilityChecked = false;
        dateError = null;

        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            dateError = "Date must be in the future.";
            availableSlots.Clear();
            return;
        }

        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        serverErrors.Remove("TimeSlot");
        Model.TimeSlot = null;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        else
            availableSlots.Clear();
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        dateError = null;
        availabilityChecked = false;

        // Client-side date check
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            dateError = "Date must be in the future.";
            return;
        }

        // Validate step-2 fields via EditContext
        editContext = new EditContext(Model);
        editContext.Validate();

        var step2Fields = new[]
        {
            nameof(Model.Doctor),
            nameof(Model.AppointmentDate),
            nameof(Model.TimeSlot),
            nameof(Model.ReasonForVisit),
        };

        bool step2Valid = step2Fields.All(f =>
            !editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (!step2Valid)
            return;

        var result = await AppointmentService.ValidatePatientAsync(Model);

        if (!result.IsValid)
        {
            serverErrors = new Dictionary<string, string>(result.FieldErrors);
            return;
        }

        availabilityChecked = true;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
        dateError = null;
        availabilityChecked = false;
    }

    private void HandleSubmit()
    {
        if (availabilityChecked)
        {
            bookingConfirmed = true;
        }
    }
}

